import Foundation

// MARK: - Container Apple ID auth: Apple WWDR chain
//
// Copied verbatim from Signed Apps (pinned 61d013e8) — the
// public WWDR intermediates + roots from zsign's embedded
// copies, used as the .p12 chain when the Container stores
// its provisioned certificate.

/// Apple WWDR intermediates (G1–G8) and roots, as DER, taken from
/// zsign's embedded copies (openssl.cpp) — the same public chain
/// certificates zsign ships so its CMS output carries the exact
/// chain Apple codesign includes. Selection is by exact match:
/// a candidate whose subject equals the leaf's issuer is the
/// intermediate; a candidate whose subject equals the
/// intermediate's issuer is its root.
enum AppleChain {
    static let certificatesDER: [Data] = [
    // C = US, O = Apple Inc., OU = Apple Worldwide Developer Relations, CN = Apple Worldwide Developer Relations Certification Authority
    "",
    // CN = Apple Worldwide Developer Relations Certification Authority, OU = G3, O = Apple Inc., C = US
    "",
    // CN = Apple Worldwide Developer Relations CA - G2, OU = Apple Certification Authority, O = Apple Inc., C = US
    "",
    // CN = Apple Worldwide Developer Relations Certification Authority, OU = G4, O = Apple Inc., C = US
    "",
    // CN = Apple Worldwide Developer Relations Certification Authority, OU = G5, O = Apple Inc., C = US
    "",
    // CN = Apple Worldwide Developer Relations Certification Authority, OU = G6, O = Apple Inc., C = US
    "",
    // C = US, O = Apple Inc., OU = G7, CN = Apple Worldwide Developer Relations Certification Authority
    "",
    // C = US, O = Apple Inc., OU = G8, CN = Apple Worldwide Developer Relations Certification Authority
    "",
    // C = US, O = Apple Inc., OU = Apple Certification Authority, CN = Apple Root CA
    "",
    // CN = Apple Root CA - G3, OU = Apple Certification Authority, O = Apple Inc., C = US
    "",    ].map { Data(base64Encoded: $0)! }
}
